css:
:root{
  --brand-primary:#2A5798;--brand-accent:#62CEE9;
  --brand-primary-700:#21406F;--brand-primary-800:#182F52;--brand-primary-050:#EEF3FA;
  --accent-600:#37B4D6;--accent-050:#E7F7FC;
  --ink:#243248;--muted:#5A6577;--line:#E2E8F0;--surface:#F5F7FA;--white:#FFFFFF;--navy-on-accent:#10233F;
  --radius:14px;--radius-sm:10px;--shadow-sm:0 4px 14px rgba(24,47,82,.08);--shadow-md:0 14px 34px rgba(24,47,82,.14);
  --maxw:1180px;--font:'Montserrat',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif;
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;font-family:var(--font);color:var(--ink);background:var(--white);font-size:17px;line-height:1.65;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--font);color:var(--brand-primary);line-height:1.18;margin:0 0 .5em;font-weight:800;letter-spacing:-.01em}
h2{font-size:clamp(1.7rem,3.4vw,2.5rem)}h3{font-size:1.28rem;font-weight:700}
p{margin:0 0 1rem}
a{color:var(--brand-primary);text-decoration:none}a:hover{text-decoration:underline}
img{max-width:100%;display:block}
.container{max-width:var(--maxw);margin:0 auto;padding:0 24px}
.section{padding:76px 0}.section--tight{padding:48px 0}
.eyebrow{font-style:italic;font-weight:700;color:var(--accent-600);text-transform:uppercase;letter-spacing:.09em;font-size:.82rem;margin:0 0 .6rem}
.eyebrow--light{color:var(--brand-accent)}
.lead{font-size:1.12rem;color:var(--muted)}
.center{text-align:center}
.skip{position:absolute;left:-999px;top:0;background:var(--brand-accent);color:var(--navy-on-accent);padding:12px 18px;border-radius:0 0 8px 0;font-weight:700;z-index:200}
.skip:focus{left:0}
.btn{display:inline-flex;align-items:center;gap:.55rem;font-weight:700;font-size:1rem;padding:14px 26px;border-radius:40px;border:2px solid transparent;cursor:pointer;transition:transform .15s ease,background .15s ease,box-shadow .15s ease;text-decoration:none;line-height:1}
.btn:hover{text-decoration:none;transform:translateY(-2px)}
.btn-accent{background:var(--brand-accent);color:var(--navy-on-accent);box-shadow:0 8px 20px rgba(98,206,233,.35)}
.btn-accent:hover{background:#4dc4e2}
.btn-primary{background:var(--brand-primary);color:#fff}.btn-primary:hover{background:var(--brand-primary-700)}
.btn-outline-light{background:transparent;color:#fff;border-color:rgba(255,255,255,.7)}.btn-outline-light:hover{background:rgba(255,255,255,.12)}
.btn-outline{background:transparent;color:var(--brand-primary);border-color:var(--brand-primary)}.btn-outline:hover{background:var(--brand-primary-050)}
.btn-lg{padding:17px 34px;font-size:1.06rem}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid var(--accent-600);outline-offset:2px;border-radius:6px}
.on-dark a:focus-visible,.on-dark button:focus-visible{outline-color:#fff}
.site-header{background:var(--brand-primary);position:sticky;top:0;z-index:100;box-shadow:0 2px 10px rgba(16,35,63,.18)}
.header-inner{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:14px 24px;max-width:var(--maxw);margin:0 auto}
.brand img{height:44px;width:auto}
.nav-toggle{display:none;background:transparent;border:0;color:#fff;font-size:1.5rem;cursor:pointer;padding:6px}
.main-nav ul{list-style:none;display:flex;align-items:center;gap:6px;margin:0;padding:0}
.main-nav a,.main-nav .drop-btn{color:#eaf1fb;font-weight:600;font-size:.98rem;padding:10px 14px;border-radius:8px;background:transparent;border:0;cursor:pointer;font-family:var(--font);display:inline-flex;align-items:center;gap:.4rem}
.main-nav a:hover,.main-nav .drop-btn:hover{color:#fff;background:rgba(255,255,255,.10);text-decoration:none}
.main-nav a[aria-current="page"]{color:var(--brand-accent)}
.has-drop{position:relative}
.drop-menu{position:absolute;top:calc(100% + 6px);left:0;min-width:240px;background:#fff;border-radius:12px;box-shadow:var(--shadow-md);padding:8px;display:none;z-index:120}
.has-drop.open .drop-menu{display:block}
.drop-menu a{display:block;color:var(--ink);font-weight:600;padding:10px 12px;border-radius:8px}
.drop-menu a:hover{background:var(--brand-primary-050);color:var(--brand-primary)}
.header-cta{display:inline-flex;align-items:center;gap:.5rem}
.header-phone{color:#fff;font-weight:700;white-space:nowrap;display:inline-flex;align-items:center;gap:.45rem}
.header-phone:hover{color:var(--brand-accent);text-decoration:none}
.hero{position:relative;background:linear-gradient(120deg,var(--brand-primary) 0%,var(--brand-primary-700) 62%,var(--brand-primary-800) 100%);color:#fff;overflow:hidden;padding:70px 0 130px}
.hero .swoosh{position:absolute;left:-6%;top:30%;width:58%;max-width:720px;opacity:.85;pointer-events:none;transform:scaleX(-1)}
.hero-grid{display:grid;grid-template-columns:.95fr 1.05fr;gap:48px;align-items:center;position:relative;z-index:2}
.hero h1{color:#fff;font-size:clamp(2.05rem,4.5vw,3.25rem);margin-bottom:.5em}
.hero h1 .hl{color:var(--brand-accent)}
.hero p.lead{color:#dbe6f5;font-size:1.16rem;max-width:36em}
.hero-coverage{display:inline-flex;align-items:center;gap:.5rem;color:#dbe6f5;font-weight:600;margin:0 0 16px;font-size:1.02rem}
.hero-coverage i{color:var(--brand-accent)}
.hero-coverage strong{color:var(--brand-accent);font-weight:700}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-top:26px}
.uptime-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:30px;padding-top:24px;border-top:1px solid rgba(255,255,255,.18)}
.uptime-row .pill{display:inline-flex;align-items:center;gap:.5rem;background:rgba(255,255,255,.10);border:1px solid rgba(255,255,255,.18);color:#eaf2fc;font-weight:600;font-size:.9rem;padding:8px 14px;border-radius:30px}
.uptime-row .pill i{color:var(--brand-accent)}
.hero-media{position:relative}
.hero-wave{position:absolute;left:0;right:0;bottom:-1px;width:100%;z-index:1;display:block}
.imgph{position:relative;background:repeating-linear-gradient(45deg,#e9eff7 0 14px,#e3ebf5 14px 28px);border:2px dashed #9fb6d6;border-radius:var(--radius);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;color:var(--brand-primary);padding:22px;min-height:220px}
.imgph .ph-tag{font-weight:800;letter-spacing:.06em;font-size:.8rem;text-transform:uppercase;background:var(--brand-primary);color:#fff;padding:5px 12px;border-radius:30px;margin-bottom:10px}
.imgph .ph-purpose{font-weight:600;color:#33456a;max-width:34ch}
.imgph .ph-meta{font-size:.78rem;color:#5f7196;margin-top:8px}
.imgph i.ph-ico{font-size:1.8rem;color:#9fb6d6;margin-bottom:6px}
.hero-media .imgph{min-height:340px;box-shadow:var(--shadow-md);background:linear-gradient(160deg,rgba(255,255,255,.16),rgba(255,255,255,.04)),repeating-linear-gradient(45deg,#3b62a0 0 16px,#345a97 16px 32px);border-color:rgba(255,255,255,.55);color:#fff}
.hero-media .imgph .ph-tag{background:var(--brand-accent);color:var(--navy-on-accent)}
.hero-media .imgph .ph-purpose{color:#eef4fc}.hero-media .imgph .ph-meta{color:#cfe0f4}.hero-media .imgph i.ph-ico{color:#cfe6f4}
.trustbar{background:#fff}
.trustbar .row{display:flex;flex-wrap:wrap;justify-content:space-between;gap:18px;text-align:center}
.trustbar .ti{flex:1 1 200px;display:flex;flex-direction:column;align-items:center;gap:2px}
.trustbar .ti i{color:var(--accent-600);font-size:1.4rem;margin-bottom:4px}
.trustbar .ti b{font-size:1.5rem;color:var(--brand-primary);font-weight:800;line-height:1}
.trustbar .ti span{color:var(--muted);font-weight:600;font-size:.92rem}
.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:center}
/* systems we support (unique) */
.systems{display:grid;grid-template-columns:repeat(2,1fr);gap:20px}
.sys{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:24px 26px;box-shadow:var(--shadow-sm);display:flex;gap:1rem;align-items:flex-start}
.sys .ic{width:50px;height:50px;border-radius:12px;background:var(--brand-primary-050);color:var(--brand-primary);border:1px solid #dbe6f5;display:flex;align-items:center;justify-content:center;font-size:1.3rem;flex:0 0 auto}
.sys h3{font-size:1.1rem;margin:0 0 .3em}
.sys p{color:var(--muted);margin:0 0 .6rem;font-size:.94rem}
.chips{display:flex;flex-wrap:wrap;gap:8px}
.chips span{background:var(--accent-050);border:1px solid #bfe6f2;color:var(--brand-primary);font-weight:600;font-size:.78rem;padding:4px 10px;border-radius:20px}
/* split checklist */
.splitlist{display:grid;grid-template-columns:1fr 1fr;gap:26px 42px}
.sl{display:flex;gap:1.1rem;align-items:flex-start}
.sl .ic{width:52px;height:52px;border-radius:12px;background:var(--brand-primary);color:#fff;display:flex;align-items:center;justify-content:center;font-size:1.35rem;flex:0 0 auto}
.sl:nth-child(even) .ic{background:linear-gradient(135deg,var(--brand-accent),var(--accent-600));color:var(--navy-on-accent)}
.sl h3{font-size:1.14rem;margin:.1em 0 .3em}
.sl p{color:var(--muted);margin:0;font-size:.96rem}
.band{background:linear-gradient(120deg,var(--brand-primary),var(--brand-primary-700));color:#fff}
.band h2{color:#fff}.band .lead{color:#d6e2f3}
.privacy-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:44px;align-items:center}
.privacy-list{list-style:none;padding:0;margin:16px 0 0}
.privacy-list li{display:flex;gap:.7rem;align-items:flex-start;margin-bottom:12px;color:#e7eefa;font-weight:500}
.privacy-list li i{color:var(--brand-accent);margin-top:5px}
.privacy-card{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);border-radius:16px;padding:28px}
.privacy-card .big{font-size:2.4rem;font-weight:800;color:var(--brand-accent);line-height:1}
.privacy-card p{color:#dbe6f5;margin:.4rem 0 0}
.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;counter-reset:step}
.step{background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:28px 24px;box-shadow:var(--shadow-sm)}
.step .num{width:44px;height:44px;border-radius:50%;background:var(--brand-accent);color:var(--navy-on-accent);font-weight:800;display:flex;align-items:center;justify-content:center;font-size:1.15rem;margin-bottom:14px}
.step .num::before{counter-increment:step;content:counter(step)}
.step h3{font-size:1.14rem}.step p{color:var(--muted);font-size:.96rem;margin:0}
.svc-links{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.svc-link{display:flex;gap:1rem;align-items:flex-start;background:#fff;border:1px solid var(--line);border-radius:var(--radius);padding:22px;box-shadow:var(--shadow-sm);transition:border-color .15s,transform .15s}
.svc-link:hover{border-color:var(--brand-accent);transform:translateY(-3px);text-decoration:none}
.svc-link i{font-size:1.35rem;color:var(--brand-primary);background:var(--accent-050);width:48px;height:48px;border-radius:10px;display:flex;align-items:center;justify-content:center;flex:0 0 auto}
.svc-link h3{font-size:1.06rem;margin:0 0 .25em}.svc-link p{color:var(--muted);font-size:.92rem;margin:0}
.svc-link .go{color:var(--accent-600);font-weight:700;font-size:.9rem;margin-top:.4rem;display:inline-flex;gap:.35rem;align-items:center}
.ind-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}
.ind{border:1px solid var(--line);border-radius:var(--radius);padding:22px;background:var(--surface);display:flex;gap:.9rem;align-items:center;font-weight:700;color:var(--brand-primary)}
.ind i{color:var(--accent-600);font-size:1.3rem}
.ind.current{background:var(--brand-primary);color:#fff;border-color:var(--brand-primary)}
.ind.current i{color:var(--brand-accent)}
.ind small{display:block;font-weight:500;color:var(--muted);font-size:.82rem}.ind.current small{color:#cfe0f4}
.faq{max-width:860px;margin:0 auto}
.faq details{background:#fff;border:1px solid var(--line);border-radius:var(--radius-sm);margin-bottom:14px;box-shadow:var(--shadow-sm);overflow:hidden}
.faq summary{list-style:none;cursor:pointer;padding:20px 22px;font-weight:700;color:var(--brand-primary);display:flex;justify-content:space-between;align-items:center;gap:1rem;font-size:1.05rem}
.faq summary::-webkit-details-marker{display:none}
.faq summary i{color:var(--accent-600);transition:transform .2s}
.faq details[open] summary i{transform:rotate(45deg)}
.faq .ans{padding:0 22px 20px;color:var(--muted)}.faq .ans p{margin:0}
.cta-band{background:linear-gradient(120deg,var(--brand-primary),var(--brand-primary-800));color:#fff}
.cta-band h2{color:#fff}
.cta-band .lead{color:#d6e2f3}
.cta-grid{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:center}
.cta-list{list-style:none;padding:0;margin:18px 0 0}
.cta-list li{display:flex;gap:.7rem;align-items:flex-start;margin-bottom:12px;color:#e7eefa;font-weight:500}
.cta-list li i{color:var(--brand-accent);margin-top:5px}
.form-card{background:#fff;border-radius:18px;padding:32px;box-shadow:var(--shadow-md);color:var(--ink)}.form-card h3{margin-top:0}
.field{margin-bottom:15px}
.field label{display:block;font-weight:600;font-size:.92rem;margin-bottom:6px;color:var(--brand-primary)}
.field label .req{color:#c0392b}
.field input,.field textarea{width:100%;padding:13px 15px;border:1.5px solid var(--line);border-radius:10px;font:inherit;font-size:1rem;color:var(--ink);background:#fff}
.field input:focus,.field textarea:focus{border-color:var(--brand-accent);outline:none;box-shadow:0 0 0 3px rgba(98,206,233,.28)}
.field textarea{min-height:96px;resize:vertical}
.hp{position:absolute;left:-9999px}
.form-note{font-size:.82rem;color:var(--muted);margin-top:2px}
.form-success{display:none;background:var(--accent-050);border:1px solid var(--brand-accent);border-radius:12px;padding:24px;text-align:center}
.form-success i{color:#1f9d55;font-size:2rem}.form-success.show{display:block}.form-success h3{color:var(--brand-primary)}
.site-footer{background:var(--brand-primary-800);color:#c9d6ea}
.footer-top{display:grid;grid-template-columns:1.5fr 1fr 1fr 1.2fr;gap:34px;padding:60px 0 40px}
.site-footer h4{color:#fff;font-size:1.02rem;letter-spacing:.02em;margin-bottom:1rem}
.site-footer a{color:#c9d6ea}.site-footer a:hover{color:var(--brand-accent)}
.foot-brand img{height:46px;margin-bottom:16px}.foot-brand p{color:#a9bbd6;font-size:.95rem;max-width:32ch}
.foot-list{list-style:none;padding:0;margin:0}.foot-list li{margin-bottom:10px;font-size:.96rem}
.foot-contact li{display:flex;gap:.65rem;align-items:flex-start;margin-bottom:12px;font-size:.96rem}
.foot-contact i{color:var(--brand-accent);margin-top:4px}
.footer-bottom{border-top:1px solid rgba(255,255,255,.12);padding:18px 0;font-size:.86rem;color:#9db0cf;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
.crumb{background:var(--surface);border-bottom:1px solid var(--line)}
.crumb ol{list-style:none;display:flex;flex-wrap:wrap;gap:.5rem;margin:0;padding:14px 0;font-size:.88rem;color:var(--muted)}
.crumb a{color:var(--muted);font-weight:600}.crumb a:hover{color:var(--brand-primary)}
.crumb li[aria-current]{color:var(--brand-primary);font-weight:700}
.crumb i{color:#b6c2d4;font-size:.7rem;margin-left:.5rem}
@media (max-width:960px){
  .hero-grid,.grid-2,.cta-grid,.privacy-grid{grid-template-columns:1fr}
  .hero .swoosh{opacity:.3}
  .systems,.splitlist,.svc-links,.ind-grid,.steps{grid-template-columns:1fr 1fr}
  .trustbar .row{gap:22px}
  .footer-top{grid-template-columns:1fr 1fr}
  .hero-media{order:-1}
  .intro-media{order:-1}
}
@media (max-width:760px){
  .nav-toggle{display:block}
  .main-nav{position:absolute;top:100%;left:0;right:0;background:var(--brand-primary-700);display:none;padding:10px 16px 18px}
  .main-nav.open{display:block}
  .main-nav ul{flex-direction:column;align-items:stretch;gap:2px}
  .main-nav a,.main-nav .drop-btn{width:100%;padding:12px 14px}
  .drop-menu{position:static;box-shadow:none;background:rgba(255,255,255,.06);margin:4px 0 4px 10px}
  .drop-menu a{color:#eaf1fb}.drop-menu a:hover{background:rgba(255,255,255,.10);color:#fff}
  .header-cta .btn{display:none}.header-inner{flex-wrap:wrap}
}
@media (max-width:540px){
  .systems,.splitlist,.svc-links,.ind-grid,.steps,.footer-top{grid-template-columns:1fr}
  .section{padding:52px 0}body{font-size:16px}
}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important;animation:none!important}}
